#!/usr/bin/env python3

import subprocess
import os

def main():
    script_path = '/tmp/workspace/cleanup.sh'

    # Set the script as executable
    try:
        os.chmod(script_path, 0o755)
        print("Made /tmp/workspace/cleanup.sh executable")
    except Exception as e:
        print(f"Failed to make script executable: {e}")
        return

    # Run the cleanup script
    try:
        result = subprocess.run(['bash', script_path], capture_output=True, text=True, timeout=30)
        print("=== SCRIPT OUTPUT ===")
        print("STDOUT:")
        print(result.stdout)
        if result.stderr:
            print("STDERR:")
            print(result.stderr)
        print(f"Return code: {result.returncode}")
        print("=== END OUTPUT ===")
    except subprocess.TimeoutExpired:
        print("Script timed out")
    except Exception as e:
        print(f"Error running script: {e}")

if __name__ == "__main__":
    main()

